<?php
use App\Http\Controllers\Api\V1\{EnterpriseGovernanceController,EnterpriseSsoController,ScimController};use App\Http\Middleware\ResolveWorkspace;use Illuminate\Support\Facades\Route;
Route::prefix('v1')->group(function(){
 Route::get('/enterprise-sso/{workspace}/{provider}/start',[EnterpriseSsoController::class,'start'])->name('enterprise.sso.start');
 Route::get('/enterprise-sso/oidc/{provider}/callback',[EnterpriseSsoController::class,'oidcCallback'])->name('enterprise.oidc.callback');
 Route::get('/enterprise-sso/saml/{provider}/metadata',[EnterpriseSsoController::class,'samlMetadata'])->name('enterprise.saml.metadata');
 Route::post('/enterprise-sso/saml/{provider}/acs',[EnterpriseSsoController::class,'samlAcs'])->name('enterprise.saml.acs');
 Route::middleware('auth:sanctum')->group(function(){Route::get('/mfa/status',[EnterpriseGovernanceController::class,'mfaStatus']);Route::post('/mfa/begin',[EnterpriseGovernanceController::class,'beginMfa']);Route::post('/mfa/confirm',[EnterpriseGovernanceController::class,'confirmMfa']);Route::post('/mfa/disable',[EnterpriseGovernanceController::class,'disableMfa']);});
 Route::middleware(['auth:sanctum',ResolveWorkspace::class,'workspace.abac:enterprise,*'])->prefix('enterprise')->group(function(){Route::get('/overview',[EnterpriseGovernanceController::class,'overview'])->middleware('workspace.permission_any:enterprise.identity.manage,enterprise.security.manage,enterprise.governance.manage');Route::post('/identity-providers',[EnterpriseGovernanceController::class,'storeProvider'])->middleware('workspace.permission:enterprise.identity.manage');Route::patch('/identity-providers/{provider}',[EnterpriseGovernanceController::class,'updateProvider'])->middleware('workspace.permission:enterprise.identity.manage');Route::post('/identity-providers/{provider}/test',[EnterpriseGovernanceController::class,'testProvider'])->middleware('workspace.permission:enterprise.identity.manage');Route::put('/security-policy',[EnterpriseGovernanceController::class,'updateSecurityPolicy'])->middleware('workspace.permission:enterprise.security.manage');Route::post('/ip-rules',[EnterpriseGovernanceController::class,'storeIpRule'])->middleware('workspace.permission:enterprise.security.manage');Route::delete('/ip-rules/{rule}',[EnterpriseGovernanceController::class,'deleteIpRule'])->middleware('workspace.permission:enterprise.security.manage');Route::post('/sessions/{session}/revoke',[EnterpriseGovernanceController::class,'revokeSession'])->middleware('workspace.permission:enterprise.security.manage');Route::post('/scim-tokens',[EnterpriseGovernanceController::class,'createScimToken'])->middleware('workspace.permission:enterprise.scim.manage');Route::post('/scim-tokens/{token}/revoke',[EnterpriseGovernanceController::class,'revokeScimToken'])->middleware('workspace.permission:enterprise.scim.manage');Route::post('/legal-entities',[EnterpriseGovernanceController::class,'storeLegalEntity'])->middleware('workspace.permission:enterprise.governance.manage');Route::post('/business-units',[EnterpriseGovernanceController::class,'storeBusinessUnit'])->middleware('workspace.permission:enterprise.governance.manage');Route::put('/members/{member}/organization',[EnterpriseGovernanceController::class,'assignMemberOrganization'])->middleware('workspace.permission:enterprise.governance.manage');Route::put('/projects/{project}/organization',[EnterpriseGovernanceController::class,'assignProjectOrganization'])->middleware('workspace.permission:enterprise.governance.manage');Route::put('/cost-centers/{costCenter}/organization',[EnterpriseGovernanceController::class,'assignCostCenterOrganization'])->middleware('workspace.permission:enterprise.governance.manage');Route::put('/governance-policies',[EnterpriseGovernanceController::class,'saveGovernancePolicy'])->middleware('workspace.permission:enterprise.governance.manage');Route::post('/access-policies',[EnterpriseGovernanceController::class,'storeAccessPolicy'])->middleware('workspace.permission:enterprise.security.manage');Route::delete('/access-policies/{policy}',[EnterpriseGovernanceController::class,'deleteAccessPolicy'])->middleware('workspace.permission:enterprise.security.manage');Route::post('/mobile-sessions/{token}/revoke',[EnterpriseGovernanceController::class,'revokeMobileSession'])->middleware('workspace.permission:enterprise.security.manage');});
});
Route::prefix('scim/v2')->middleware(['scim.auth','workspace.module:enterprise','throttle:240,1'])->group(function(){
 Route::get('/ServiceProviderConfig',[ScimController::class,'serviceProviderConfig']);
 Route::get('/Schemas',[ScimController::class,'schemas']);
 Route::get('/ResourceTypes',[ScimController::class,'resourceTypes']);
 Route::get('/Users',[ScimController::class,'users'])->middleware('scim.scope:users.read');
 Route::post('/Users',[ScimController::class,'storeUser'])->middleware('scim.scope:users.write');
 Route::get('/Users/{id}',[ScimController::class,'showUser'])->middleware('scim.scope:users.read');
 Route::patch('/Users/{id}',[ScimController::class,'patchUser'])->middleware('scim.scope:users.write');
 Route::delete('/Users/{id}',[ScimController::class,'deleteUser'])->middleware('scim.scope:users.write');
 Route::get('/Groups',[ScimController::class,'groups'])->middleware('scim.scope:groups.read');
 Route::patch('/Groups/{id}',[ScimController::class,'patchGroup'])->middleware('scim.scope:groups.write');
});
